[{"id": "call_s2jopvwf", "function": {"index": 0, "name": "write_file", "arguments": {"content": "def read_settings(text):
    settings = {}
    lines = text.splitlines()
    for line in lines:
        # Ignore blank lines and lines starting with #
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        # Find the first '=' and split
        if '=' not in stripped_line:
            raise ValueError(f"Malformed line: {stripped_line}")

        key, value = stripped_line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key:
            raise ValueError(f"Malformed line: missing key in '{stripped_line}'")

        if key in settings:
            raise ValueError(f"Duplicate key found: {key}")

        if key == 'endpoint' and value not in ['true', 'false']:
            raise ValueError(f"Invalid value for 'endpoint': {value}. Must be 'true' or 'false'")

        if key == 'enabled':
            settings[key] = (value == 'true')
        elif key != 'endpoint':
            settings[key] = value
        else:
            # This handles keys that are not 'endpoint' or 'enabled' but are present.
            # The requirement says: Required keys endpoint and enabled. 
            # Duplicate keys, malformed lines, unknown keys or missing keys raise ValueError.
            # I will treat keys other than 'endpoint' or 'enabled' as unknown and raise an error.
            raise ValueError(f"Unknown key found: {key}")

    # Check for missing required keys
    if 'endpoint' not in settings or 'enabled' not in settings:
        raise ValueError("Missing required key(s): 'endpoint' and 'enabled'")

    return settings"}}}]
